#!name=微信公众号
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = mp.weixin.qq.com

[Rewrite]
response if ${url} ~= /^https?:\/\/mp\.weixin\.qq\.com\/mp\/getappmsgad/i then response.body.replace(/advertisement/, "fmz200")
request if ${url} ~= /^https?:\/\/mp\.weixin\.qq\.com\/mp\/cps_product_info\?action/i then reject_dict(200)
